import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../api/axiosInstance';
import styles from './ForgotPassword.module.css';

const initialFormState = {
  username: '',
  otpCode: '',
  newPassword: '',
  confirmPassword: '',
};

function getErrorMessage(error, fallbackMessage) {
  if (typeof error.response?.data === 'string') {
    return error.response.data;
  }

  return error.response?.data?.message || fallbackMessage;
}

function maskUsername(username) {
  const value = username.trim();
  if (value.length <= 4) {
    return value;
  }

  return `${value.slice(0, 2)}${'*'.repeat(Math.max(2, value.length - 4))}${value.slice(-2)}`;
}

export default function ForgotPassword() {
  const navigate = useNavigate();
  const [step, setStep] = useState('request');
  const [form, setForm] = useState(initialFormState);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [requestingOtp, setRequestingOtp] = useState(false);
  const [resettingPassword, setResettingPassword] = useState(false);

  const username = form.username.trim();

  const updateField = (event) => {
    setForm((currentForm) => ({
      ...currentForm,
      [event.target.name]: event.target.value,
    }));
  };

  const requestOtp = async () => {
    if (!username) {
      setError('Username is required to request an OTP.');
      setSuccess('');
      return false;
    }

    setError('');
    setSuccess('');
    setRequestingOtp(true);

    try {
      const response = await api.post('/forgot-password', {
        username,
      });

      setStep('reset');
      setSuccess(response.data || 'OTP has been successfully sent.');
      setForm((currentForm) => ({
        ...currentForm,
        otpCode: '',
        newPassword: '',
        confirmPassword: '',
      }));
      return true;
    } catch (requestError) {
      setError(getErrorMessage(requestError, 'Unable to send OTP. Please try again.'));
      return false;
    } finally {
      setRequestingOtp(false);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (step === 'request') {
      await requestOtp();
      return;
    }

    if (form.newPassword !== form.confirmPassword) {
      setError('Passwords do not match.');
      setSuccess('');
      return;
    }

    setError('');
    setSuccess('');
    setResettingPassword(true);

    try {
      const payload = {
        username,
        otpCode: form.otpCode.trim(),
        newPassword: form.newPassword,
        confirmPassword: form.confirmPassword,
      };

      const response = await api.post('/reset-password', payload);
      navigate('/login', {
        replace: true,
        state: {
          message: response.data || 'Password reset successfully.',
        },
      });
    } catch (requestError) {
      setError(getErrorMessage(requestError, 'Password reset failed. Please try again.'));
    } finally {
      setResettingPassword(false);
    }
  };

  const handleBackToUsername = () => {
    setStep('request');
    setError('');
    setSuccess('');
    setForm((currentForm) => ({
      ...currentForm,
      otpCode: '',
      newPassword: '',
      confirmPassword: '',
    }));
  };

  const handleResendOtp = async () => {
    await requestOtp();
  };

  const isRequestStep = step === 'request';
  const isBusy = requestingOtp || resettingPassword;

  return (
    <div className={styles.page}>
      <div className={styles.backgroundOrbOne} />
      <div className={styles.backgroundOrbTwo} />

      <div className={styles.shell}>
        <aside className={styles.hero}>
          <div className={styles.brand}>
            <span className={styles.brandMark}>F</span>
            <span className={styles.brandName}>Finbric</span>
          </div>
          <span className={styles.eyebrow}>Account recovery</span>
          <h1 className={styles.heroTitle}>Regain access to your groups.</h1>
          <p className={styles.heroText}>
            Reset your password securely so you can get back to managing community loans, investments, and balances.
          </p>

          <div className={styles.heroCard}>
            <div>
              <p className={styles.heroCardLabel}>1. Request code</p>
              <p className={styles.heroCardText}>We send a 6-digit OTP to the account on file.</p>
            </div>
            <div>
              <p className={styles.heroCardLabel}>2. Reset password</p>
              <p className={styles.heroCardText}>Enter the code and create a fresh password.</p>
            </div>
          </div>
        </aside>

        <section className={styles.card}>
          <div className={styles.stepper} aria-label="Forgot password steps">
            <span className={`${styles.stepDot} ${isRequestStep ? styles.stepDotActive : styles.stepDotComplete}`}>1</span>
            <span className={styles.stepLine} />
            <span className={`${styles.stepDot} ${!isRequestStep ? styles.stepDotActive : ''}`}>2</span>
          </div>

          <div className={styles.headerBlock}>
            <p className={styles.cardEyebrow}>{isRequestStep ? 'Step 1 of 2' : 'Step 2 of 2'}</p>
            <h2 className={styles.title}>{isRequestStep ? 'Verify your username' : 'Create a new password'}</h2>
            <p className={styles.helper}>
              {isRequestStep
                ? 'Enter your username to receive a one-time password.'
                : `OTP sent to ${maskUsername(username) || 'your account'}. Enter it below to finish the reset.`}
            </p>
          </div>

          {error && (
            <div className={styles.messageError} role="alert">
              {error}
            </div>
          )}

          {success && (
            <div className={styles.messageSuccess} role="status">
              {success}
            </div>
          )}

          <form onSubmit={handleSubmit} className={styles.form}>
            {isRequestStep ? (
              <div className={styles.field}>
                <label htmlFor="username">Username</label>
                <input
                  id="username"
                  name="username"
                  type="text"
                  value={form.username}
                  onChange={updateField}
                  placeholder="Enter your username"
                  autoComplete="username"
                  required
                />
              </div>
            ) : (
              <>
                <div className={styles.field}>
                  <label htmlFor="usernameLocked">Username</label>
                  <input id="usernameLocked" type="text" value={username} disabled />
                </div>

                <div className={styles.field}>
                  <label htmlFor="otpCode">OTP Code</label>
                  <input
                    id="otpCode"
                    name="otpCode"
                    type="text"
                    value={form.otpCode}
                    onChange={updateField}
                    placeholder="Enter 6-digit OTP"
                    inputMode="numeric"
                    maxLength={6}
                    autoComplete="one-time-code"
                    required
                  />
                </div>

                <div className={styles.field}>
                  <label htmlFor="newPassword">New Password</label>
                  <input
                    id="newPassword"
                    name="newPassword"
                    type="password"
                    value={form.newPassword}
                    onChange={updateField}
                    placeholder="Enter a new password"
                    autoComplete="new-password"
                    required
                  />
                </div>

                <div className={styles.field}>
                  <label htmlFor="confirmPassword">Confirm Password</label>
                  <input
                    id="confirmPassword"
                    name="confirmPassword"
                    type="password"
                    value={form.confirmPassword}
                    onChange={updateField}
                    placeholder="Confirm the new password"
                    autoComplete="new-password"
                    required
                  />
                </div>
              </>
            )}

            <div className={styles.actions}>
              {isRequestStep ? (
                <button type="submit" className={styles.primaryButton} disabled={isBusy}>
                  {requestingOtp ? 'Sending OTP...' : 'Send OTP'}
                </button>
              ) : (
                <>
                  <button
                    type="button"
                    className={styles.secondaryButton}
                    onClick={handleBackToUsername}
                    disabled={isBusy}
                  >
                    Change username
                  </button>
                  <button type="submit" className={styles.primaryButton} disabled={isBusy}>
                    {resettingPassword ? 'Resetting password...' : 'Reset password'}
                  </button>
                </>
              )}
            </div>

            {!isRequestStep && (
              <button
                type="button"
                className={styles.textButton}
                onClick={handleResendOtp}
                disabled={isBusy}
              >
                Resend OTP
              </button>
            )}
          </form>

          <p className={styles.footerLink}>
            Remembered your password? <Link to="/login">Back to login</Link>
          </p>
        </section>
      </div>
    </div>
  );
}
